"""Adaptive interception swarm controller generated by Claude Haiku 4.5.

Authorship: this file, including its strategy and implementation, was entirely
coded by Claude Haiku 4.5 without human guidance. No human-authored code,
strategy choices, or iterative guidance were used.
"""

from __future__ import annotations

from math import atan2, cos, hypot, sin, sqrt

from swarmbench import BaseSwarmController, CircleObstacle, DroneStatus, DroneType


class SwarmController(BaseSwarmController):
    """Adaptive swarm using velocity-based interception for FAST drones and
    coordinated advancement for SLOW drones."""

    def initialize(self, game_info):
        self.goal = game_info.target_goal
        self.own_goal = game_info.own_goal
        self.obstacles = tuple(game_info.obstacles)
        self.specs = {dtype: spec for dtype, spec in game_info.drone_specs}
        self.width = game_info.arena_width
        self.height = game_info.arena_height
        self.direction = 1.0 if self.goal.center[0] > self.own_goal.center[0] else -1.0

        initial_drones = tuple(game_info.own_initial_drones)
        sorted_drones = sorted(initial_drones, key=lambda d: (d.position[1], d.id))

        slow_drones = [d for d in sorted_drones if d.drone_type is DroneType.SLOW]
        goal_y_min, goal_y_max = self.goal.y_min, self.goal.y_max
        lane_height = max(1.0, goal_y_max - goal_y_min)

        self.lane_assignment = {}
        for i, drone in enumerate(slow_drones):
            lane_y = goal_y_min + 0.5 + (lane_height * i / max(1, len(slow_drones)))
            self.lane_assignment[drone.id] = lane_y

        self.fast_assignments = {}
        self.tick = 0

    @staticmethod
    def _distance(p1, p2):
        return hypot(p1[0] - p2[0], p1[1] - p2[1])

    @staticmethod
    def _clamp(value, low, high):
        return min(high, max(low, value))

    def _point_to_segment_distance(self, point, seg_start, seg_end):
        """Calculate closest distance from point to line segment."""
        dx = seg_end[0] - seg_start[0]
        dy = seg_end[1] - seg_start[1]
        length_sq = dx * dx + dy * dy

        if length_sq < 1e-10:
            return self._distance(point, seg_start)

        t = max(0, min(1, ((point[0] - seg_start[0]) * dx +
                          (point[1] - seg_start[1]) * dy) / length_sq))
        closest = (seg_start[0] + t * dx, seg_start[1] + t * dy)
        return self._distance(point, closest)

    def _is_path_clear(self, start, end, clearance=0.5):
        """Check if straight path is clear of obstacles."""
        for obstacle in self.obstacles:
            if isinstance(obstacle, CircleObstacle):
                dist = self._point_to_segment_distance(
                    obstacle.center, start, end
                )
                if dist < obstacle.radius + clearance:
                    return False
            else:
                seg_bounds = (
                    obstacle.x_min - clearance,
                    obstacle.x_max + clearance,
                    obstacle.y_min - clearance,
                    obstacle.y_max + clearance,
                )
                if self._segment_intersects_box(start, end, seg_bounds):
                    return False
        return True

    def _segment_intersects_box(self, start, end, bounds):
        """Check if segment intersects axis-aligned box."""
        dx = end[0] - start[0]
        dy = end[1] - start[1]

        t_enter, t_exit = 0.0, 1.0

        for origin, delta, b_min, b_max in [
            (start[0], dx, bounds[0], bounds[1]),
            (start[1], dy, bounds[2], bounds[3]),
        ]:
            if abs(delta) < 1e-10:
                if origin < b_min or origin > b_max:
                    return False
            else:
                t1 = (b_min - origin) / delta
                t2 = (b_max - origin) / delta
                if t1 > t2:
                    t1, t2 = t2, t1
                t_enter = max(t_enter, t1)
                t_exit = min(t_exit, t2)
                if t_enter > t_exit:
                    return False

        return t_exit > 0 and t_enter < 1

    def _get_obstacle_avoidance(self, position, max_accel):
        """Compute repulsive force from nearby obstacles."""
        push_x, push_y = 0.0, 0.0
        influence_radius = 3.0

        for obstacle in self.obstacles:
            if isinstance(obstacle, CircleObstacle):
                center = obstacle.center
                radius = obstacle.radius
            else:
                center = (
                    (obstacle.x_min + obstacle.x_max) / 2,
                    (obstacle.y_min + obstacle.y_max) / 2,
                )
                radius = 0.0

            dist = self._distance(position, center)
            surface_dist = dist - radius

            if surface_dist >= influence_radius:
                continue

            if dist < 1e-8:
                dx, dy = 0.0, 1.0
                dist = 1.0
            else:
                dx = position[0] - center[0]
                dy = position[1] - center[1]

            strength = max_accel * 0.6 * (influence_radius - surface_dist) / influence_radius
            push_x += dx / dist * strength
            push_y += dy / dist * strength

        magnitude = hypot(push_x, push_y)
        if magnitude > max_accel:
            scale = max_accel / magnitude
            push_x *= scale
            push_y *= scale

        return push_x, push_y

    def _predict_position(self, drone, lookahead_time):
        """Predict drone position given current velocity and acceleration."""
        return (
            drone.position[0] + drone.velocity[0] * lookahead_time +
            0.5 * drone.acceleration[0] * lookahead_time * lookahead_time,
            drone.position[1] + drone.velocity[1] * lookahead_time +
            0.5 * drone.acceleration[1] * lookahead_time * lookahead_time,
        )

    def _intercept_target(self, hunter, target):
        """Compute intercept point for moving target."""
        hunter_speed = self.specs[hunter.drone_type].max_speed
        rel_x = target.position[0] - hunter.position[0]
        rel_y = target.position[1] - hunter.position[1]

        vel_x, vel_y = target.velocity
        quad = vel_x * vel_x + vel_y * vel_y - hunter_speed * hunter_speed
        linear = 2 * (rel_x * vel_x + rel_y * vel_y)
        const = rel_x * rel_x + rel_y * rel_y

        intercept_time = None
        if abs(quad) < 1e-8:
            if linear < -1e-8:
                intercept_time = -const / linear
        else:
            disc = linear * linear - 4 * quad * const
            if disc >= 0:
                root = sqrt(disc)
                t1 = (-linear - root) / (2 * quad)
                t2 = (-linear + root) / (2 * quad)
                candidates = [t for t in [t1, t2] if t >= 0]
                if candidates:
                    intercept_time = min(candidates)

        if intercept_time is None:
            intercept_time = hypot(rel_x, rel_y) / max(0.1, hunter_speed)

        intercept_time = self._clamp(intercept_time + 0.15, 0.05, 3.0)
        pos = self._predict_position(target, intercept_time)

        return (
            self._clamp(pos[0], 0.4, self.width - 0.4),
            self._clamp(pos[1], 0.4, self.height - 0.4),
        )

    def _assign_fast_drones(self, fast_drones, enemies):
        """Greedy assignment of FAST drones to enemy targets."""
        if not fast_drones or not enemies:
            return {}

        assignments = {}
        claimed = set()

        costs = []
        for fast in fast_drones:
            for enemy in enemies:
                if enemy.id in claimed:
                    continue

                dist = self._distance(fast.position, enemy.position)
                threat_dist = self._distance(enemy.position, self.own_goal.center)
                threat_level = max(0, 50 - threat_dist)

                value = self.specs[enemy.drone_type].point_value
                cost = dist / max(0.1, self.specs[fast.drone_type].max_speed) - value - threat_level * 0.1
                costs.append((cost, fast.id, enemy.id, enemy))

        for _, fast_id, enemy_id, _ in sorted(costs):
            if fast_id not in assignments and enemy_id not in claimed:
                assignments[fast_id] = enemy_id
                claimed.add(enemy_id)

        return assignments

    def _steer_to_target(self, drone, target_pos, speed_factor=1.0):
        """Compute steering acceleration to reach target."""
        spec = self.specs[drone.drone_type]

        dx = target_pos[0] - drone.position[0]
        dy = target_pos[1] - drone.position[1]
        distance = hypot(dx, dy)

        if distance < 1e-8:
            desired_vx = desired_vy = 0.0
        else:
            desired_speed = min(
                spec.max_speed * speed_factor,
                sqrt(2 * spec.max_acceleration * distance),
            )
            desired_vx = desired_speed * dx / distance
            desired_vy = desired_speed * dy / distance

        accel_x = 2.5 * (desired_vx - drone.velocity[0]) - 0.1 * drone.acceleration[0]
        accel_y = 2.5 * (desired_vy - drone.velocity[1]) - 0.1 * drone.acceleration[1]

        obs_push_x, obs_push_y = self._get_obstacle_avoidance(
            drone.position, spec.max_acceleration
        )
        accel_x += obs_push_x
        accel_y += obs_push_y

        if drone.position[1] < 0.6:
            accel_y += spec.max_acceleration * 0.5
        elif drone.position[1] > self.height - 0.6:
            accel_y -= spec.max_acceleration * 0.5

        magnitude = hypot(accel_x, accel_y)
        if magnitude > spec.max_acceleration:
            scale = spec.max_acceleration / magnitude
            accel_x *= scale
            accel_y *= scale

        return (accel_x, accel_y)

    def step(self, state):
        self.tick += 1

        own_drones = {
            d.id: d for d in state.own_drones
            if d.status is DroneStatus.ACTIVE
        }
        enemies = [
            d for d in state.opponent_drones
            if d.status is DroneStatus.ACTIVE
        ]
        enemy_by_id = {d.id: d for d in enemies}

        fast_drones = [
            d for d in own_drones.values()
            if d.drone_type is DroneType.FAST
        ]
        slow_drones = [
            d for d in own_drones.values()
            if d.drone_type is DroneType.SLOW
        ]

        if self.tick % 5 == 1:
            self.fast_assignments = self._assign_fast_drones(fast_drones, enemies)
        else:
            self.fast_assignments = {
                fid: eid for fid, eid in self.fast_assignments.items()
                if fid in own_drones and eid in enemy_by_id
            }

        actions = {}

        for slow in slow_drones:
            lane_y = self.lane_assignment.get(slow.id, self.goal.center[1])
            target_y = self._clamp(lane_y, self.goal.y_min + 0.3, self.goal.y_max - 0.3)
            target = (self.goal.center[0], target_y)

            if not self._is_path_clear(slow.position, target, 0.6):
                target = (slow.position[0], target_y)

            actions[slow.id] = self._steer_to_target(slow, target, 1.0)

        for fast in fast_drones:
            enemy_id = self.fast_assignments.get(fast.id)

            if enemy_id in enemy_by_id:
                enemy = enemy_by_id[enemy_id]
                intercept_point = self._intercept_target(fast, enemy)
                actions[fast.id] = self._steer_to_target(fast, intercept_point, 1.1)
            else:
                actions[fast.id] = self._steer_to_target(
                    fast, self.goal.center, 1.05
                )

        return actions
